var FB_SDK_SRC="https://connect.facebook.net/en_US/sdk.js";var FB_GRAPH_VERSION="v23.0";function facebookAppId(){return typeof APP_CONFIG!=="undefined"&&APP_CONFIG.FACEBOOK_APP_ID||""}function initFacebookSignIn(){var wrap=document.getElementById("facebook-signin-wrap");var btn=document.getElementById("facebook-signin-btn");if(!wrap||!btn||!facebookAppId())return;wrap.hidden=false;if(btn.dataset.wired)return;btn.dataset.wired="1";btn.addEventListener("click",onFacebookClick)}function loadFacebookSdk(done){if(window.FB)return done(true);var timer=setTimeout(function(){done(false)},15e3);window.fbAsyncInit=function(){clearTimeout(timer);try{FB.init({appId:facebookAppId(),cookie:false,xfbml:false,version:FB_GRAPH_VERSION});done(true)}catch(e){done(false)}};var s=document.createElement("script");s.src=FB_SDK_SRC;s.async=true;s.defer=true;s.crossOrigin="anonymous";s.onerror=function(){clearTimeout(timer);done(false)};document.head.appendChild(s)}function onFacebookClick(){var btn=document.getElementById("facebook-signin-btn");var errorEl=document.getElementById("facebook-signin-error");if(errorEl)errorEl.textContent="";var busyDone=typeof setButtonBusy==="function"?setButtonBusy(btn,"Opening Facebook"):function(){};loadFacebookSdk(function(loaded){if(!loaded||!window.FB){busyDone();if(errorEl)errorEl.textContent="Facebook could not be reached. Please try again, or use your email.";return}FB.login(async function(response){var auth=response&&response.authResponse;if(!auth||!auth.accessToken){busyDone();if(errorEl)errorEl.textContent="Facebook sign-in did not complete. Please try again.";return}var res=await Api.post("facebookSignIn",providerSignInBody({accessToken:auth.accessToken}));busyDone();handleProviderResult(res,errorEl,"Facebook")},{scope:"public_profile,email"})})}document.addEventListener("DOMContentLoaded",function(){if(window.FACEBOOK_SIGNIN_DEFER)return;initFacebookSignIn()});